    know_ok RSEGS E M kn -> existsb (is_kimg_cov a 31) kn = true ->
    rdn RSEGS (fun _ => None) (Z_to_bv 64 a) 31 = Some bs -> (0 <= a)%Z -> (a + 31 < 2 ^ 64)%Z ->
    rdn RSEGS M (Z_to_bv 64 a) 31 = Some bs.
